// @ts-expect-error
import { api } from "../../../scripts/api.js";

(window as unknown as { api: unknown }).api = api;

import type { Favorite, MeldImage, Settings, Tag } from "./types";

export const fetchImages = async (
	offset = 0,
	limit = 30,
	query = "",
): Promise<{
	images: MeldImage[];
	total: number;
	offset: number;
	limit: number;
}> => {
	const res = await api.fetchApi(
		`/meld-nexus/list?offset=${offset}&limit=${limit}&query=${encodeURIComponent(query)}`,
	);
	if (!res.ok) {
		throw new Error(`Failed to fetch images: ${res.statusText}`);
	}
	return await res.json();
};

export const fetchSuggestions = async (
	query: string,
	type?: string,
): Promise<
	{
		type: string;
		value: string;
		count: number;
	}[]
> => {
	const url = `/meld-nexus/suggest?query=${encodeURIComponent(query)}${type ? `&type=${type}` : ""}`;
	const res = await api.fetchApi(url);
	if (!res.ok) {
		return [];
	}
	return await res.json();
};

